// Window to check: from now to the last bookable day (Negocio.dias_max_agenda).
// Ventana a revisar: desde ahora hasta el último día agendable.
const n = $('When Called').first().json.negocio || {};
const tz = n.zona_horaria || 'America/Phoenix';
const now = $now.setZone(tz);
const timeMin = now.toISO();
const timeMax = now.plus({ days: Number(n.dias_max_agenda) || 14 }).endOf('day').toISO();
return [{ json: {
  calendar_id: n.calendar_id,
  body: { timeMin, timeMax, timeZone: tz, items: [{ id: n.calendar_id }] }
} }];

// Free 1-hour blocks inside business hours, with the minimum notice. Rules come from the Negocio sheet.
// Bloques libres de 1 hora dentro del horario, con la anticipación mínima. Las reglas salen de la hoja Negocio.
const n = $('When Called').first().json.negocio || {};
const calId = $('Build Range').first().json.calendar_id;
const tz = n.zona_horaria || 'America/Phoenix';
const BLOCK = Number(n.bloque_min) || 60;
const res = $input.first().json || {};
const cal = (res.calendars || {})[calId] || {};
if (cal.errors) throw new Error('Calendar freeBusy: ' + JSON.stringify(cal.errors));
const busy = (cal.busy || []).map(b => ({ s: DateTime.fromISO(b.start).toMillis(), e: DateTime.fromISO(b.end).toMillis() }));

// Hours per weekday (Luxon: 1 = Monday ... 7 = Sunday)
const parse = v => { const m = String(v || '').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/); return m ? { o: +m[1] * 60 + +m[2], c: +m[3] * 60 + +m[4] } : null; };
const HOURS = { 1: parse(n.horario_lun_vie), 2: parse(n.horario_lun_vie), 3: parse(n.horario_lun_vie), 4: parse(n.horario_lun_vie), 5: parse(n.horario_lun_vie), 6: parse(n.horario_sab), 7: parse(n.horario_dom) };

const now = $now.setZone(tz);
const earliest = now.plus({ hours: Number(n.anticipacion_min_horas) || 2 }).toMillis();
const days = Number(n.dias_max_agenda) || 14;
const free = [];
const lines = [];
for (let d = 0; d <= days; d++) {
  const day = now.plus({ days: d }).startOf('day');
  const h = HOURS[day.weekday];
  if (!h) continue;
  const times = [];
  for (let m = h.o; m + BLOCK <= h.c; m += BLOCK) {
    const s = day.plus({ minutes: m });
    const sm = s.toMillis(), em = sm + BLOCK * 60000;
    if (sm < earliest) continue;
    if (busy.some(b => b.s < em && b.e > sm)) continue;
    free.push(s.toFormat('yyyy-MM-dd HH:mm'));
    times.push(s.toFormat('HH:mm'));
  }
  if (times.length) lines.push(day.setLocale('en').toFormat('ccc yyyy-MM-dd') + ': ' + times.join(', '));
}

return [{ json: {
  ok: true,
  block_min: BLOCK,
  free_blocks: free,                                  // ['2026-10-23 09:00', ...]
  slots_text: lines.join('\n') || 'No free slots in the next ' + days + ' days.',
  generated_at: now.toFormat('yyyy-MM-dd HH:mm')
} }];
